    /** A "class NUMERIC" test for a DISPLAY field (all characters are digits). */
    private static boolean isNumeric(String s) {
        if (s.isEmpty()) {
            return false;
        }
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    /** Return a string of n spaces (COBOL X-field initial content). */
    private static String spaces(int n) {
        return " ".repeat(n);
    }

    /** Coerce an input line into a fixed-width alphanumeric field of n bytes. */
    private static String fixed(String s, int n) {
        if (s.length() >= n) {
            return s.substring(0, n);
        }
        return s + spaces(n - s.length());
    }
